#!/usr/bin/env node
// Generates components/core/Icon.jsx and the IconName union in Icon.d.ts from the
// vendored Lucide SVGs in assets/icons/lucide/.
//
//   node scripts/build-icons.mjs          # write
//   node scripts/build-icons.mjs --check  # fail if the generated files are out of date
//
// To add an icon: drop its SVG into assets/icons/lucide/ (from
// https://cdn.jsdelivr.net/npm/lucide-static@<version>/icons/<name>.svg) and re-run.
// Do not hand-draw icons and do not paste one-off SVGs into a page — the point of
// this pipeline is that every glyph in the system comes from one consistent set.
//
// Lucide is ISC-licensed; assets/icons/lucide/LICENSE ships with the icons.

import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SRC = join(ROOT, 'assets/icons/lucide');
const checkOnly = process.argv.includes('--check');

const ATTR = {
  'stroke-width': 'strokeWidth', 'stroke-linecap': 'strokeLinecap', 'stroke-linejoin': 'strokeLinejoin',
  'fill-rule': 'fillRule', 'clip-rule': 'clipRule', 'stroke-dasharray': 'strokeDasharray',
};
const DROP = new Set(['class', 'xmlns', 'stroke', 'fill', 'width', 'height', 'viewBox']);

const files = readdirSync(SRC).filter((f) => f.endsWith('.svg')).sort();
const icons = [];
for (const file of files) {
  const svg = readFileSync(join(SRC, file), 'utf8');
  const inner = svg.slice(svg.indexOf('>', svg.indexOf('<svg')) + 1, svg.lastIndexOf('</svg>'));
  const parts = [];
  for (const el of inner.matchAll(/<(path|circle|rect|line|polyline|polygon|ellipse)\b([^>]*?)\/?>/g)) {
    const attrs = {};
    for (const a of el[2].matchAll(/([\w-]+)="([^"]*)"/g)) {
      if (DROP.has(a[1])) continue;
      attrs[ATTR[a[1]] ?? a[1]] = a[2];
    }
    parts.push([el[1], attrs]);
  }
  if (!parts.length) { console.error(`${file}: no drawable elements found`); process.exitCode = 1; continue; }
  icons.push([file.replace(/\.svg$/, ''), parts]);
}

const version = (readFileSync(join(SRC, files[0]), 'utf8').match(/lucide-static v([\d.]+)/) ?? [])[1] ?? 'unknown';

const body = icons
  .map(([name, parts]) => {
    const els = parts
      .map(([tag, attrs]) => `['${tag}',{${Object.entries(attrs).map(([k, v]) => `${/^[a-z][\w]*$/i.test(k) ? k : `'${k}'`}:'${v}'`).join(',')}}]`)
      .join(',');
    return `  '${name}': [${els}],`;
  })
  .join('\n');

const jsx = `import React from 'react';
// GENERATED by scripts/build-icons.mjs — do not edit by hand.
// Source: Lucide v${version} (ISC), vendored in assets/icons/lucide/ with its LICENSE.
// 24×24 grid, 2px stroke, currentColor — add a glyph by dropping its SVG in that
// folder and re-running the script. Never hand-draw a one-off icon in a page.
const ICONS = {
${body}
};

export function Icon({ name, size = 20, strokeWidth = 2, color = 'currentColor', title }) {
  const parts = ICONS[name];
  if (!parts) return null;
  const a11y = title ? { role: 'img', 'aria-label': title } : { 'aria-hidden': 'true', focusable: 'false' };
  return React.createElement('svg', {
    viewBox: '0 0 24 24', width: size, height: size, fill: 'none',
    stroke: color, strokeWidth, strokeLinecap: 'round', strokeLinejoin: 'round',
    style: { display: 'inline-block', flexShrink: 0, verticalAlign: 'middle' }, ...a11y
  }, parts.map(([tag, attrs], i) => React.createElement(tag, { key: i, ...attrs })));
}

export const iconNames = Object.keys(ICONS);
`;

const dtsPath = join(ROOT, 'components/core/Icon.d.ts');
const dts = `import React from 'react';

// GENERATED list — see scripts/build-icons.mjs. ${icons.length} glyphs from Lucide v${version} (ISC).
export type IconName =
${icons.map(([n]) => `  | '${n}'`).join('\n')};

export interface IconProps {
  /** Which glyph to render */
  name: IconName;
  /** Pixel size (width & height), default 20 */
  size?: number;
  /** Stroke weight, default 2 — the grid these icons are drawn on */
  strokeWidth?: number;
  /** Stroke colour; defaults to currentColor so it inherits text colour */
  color?: string;
  /** Accessible label. Omit for decorative icons (rendered aria-hidden) */
  title?: string;
}

/**
 * Line-icon primitive — the single source of truth for iconography.
 * 24×24 grid, 2px stroke, inherits \`currentColor\`. Pass to Button/IconButton via \`icon\`.
 * Returns null for an unknown name, so a typo fails visibly in review rather than
 * rendering a broken glyph.
 */
export function Icon(props: IconProps): JSX.Element | null;

/** All available icon names, alphabetical */
export const iconNames: IconName[];
`;

const targets = { 'components/core/Icon.jsx': jsx, 'components/core/Icon.d.ts': dts };
let stale = false;
for (const [rel, content] of Object.entries(targets)) {
  const p = join(ROOT, rel);
  if (existsSync(p) && readFileSync(p, 'utf8') === content) continue;
  stale = true;
  if (checkOnly) { console.log(`out of date: ${rel}`); continue; }
  writeFileSync(p, content);
  console.log(`wrote ${rel}`);
}
if (!stale) console.log(`icons up to date (${icons.length} glyphs, Lucide v${version})`);
else if (!checkOnly) console.log(`${icons.length} glyphs from Lucide v${version} — run "npm run sync" to mirror into dist/rse.js`);
process.exit(checkOnly && stale ? 1 : process.exitCode ?? 0);
